-- Schema version 8: claim ownership tokens.
-- A claim is now named: the claim writes a random token, and every
-- heartbeat and stamp matches it. Before the token, a runner whose
-- lease had lapsed (a stall past ten minutes) kept heartbeating a row
-- another runner had re-claimed -- two runners on one row, each
-- keeping the other's lease alive. With the token, the dispossessed
-- runner's next heartbeat changes nothing and it learns to let go.
-- The token is generated by the database (randomblob), so no crate
-- gains a random dependency for it.
ALTER TABLE enrichment_queue ADD COLUMN claim_token TEXT;
ALTER TABLE asset_queue ADD COLUMN claim_token TEXT;
